"Ten beads make a lantern.":"عشر خرزات تصنع فانوسًا.",
"Will you help me light the Kingdom?":"هل تساعدني على إضاءة المملكة؟",
"Hint":"تلميح",
"Try again.":"حاول مرة أخرى.",
"Homeschool or not sure":"تعليم منزلي أو غير متأكد",
"How long we keep it":"مدة الاحتفاظ",
"How we use it":"كيف نستخدمها",
"How we'll know":"كيف سنعرف",
"Hundreds are the same, so look at the ones.":"المئات متساوية، فانظر إلى الآحاد.",
"I agree that Tenbright may keep my child's learning record on this device to choose their next activity and show me their progress.":"أوافق على أن يحتفظ Tenbright بسجل تعلّم طفلي على هذا الجهاز لاختيار نشاطه التالي وعرض تقدّمه لي.",
"I am this child's parent or legal guardian.":"أنا والد هذا الطفل أو وصيّه القانوني.",
"I found {N} lanterns you can already light.":"وجدت {N} فوانيس يمكنك إضاءتها من الآن.",
"Now the map knows where to start.":"الآن تعرف الخريطة من أين نبدأ.",
"I worked this out, but I made a mistake.":"حللت هذه المسألة، لكنني أخطأت.",
"Can you find it?":"هل تستطيع أن تجد الخطأ؟",
"I wrote it":"كتبتها",
"If we change what we collect or how we use it, we will ask for your consent again before the change applies to your child.":"إذا غيّرنا ما نجمعه أو طريقة استخدامه، فسنطلب موافقتك مرة أخرى قبل تطبيق التغيير على طفلك.",
"If you switch on voice answers on the grown-ups page, your child can tap the Talk button and say a number or a short command such as \"next\".":"إذا فعّلت الإجابات الصوتية في صفحة الكبار، يستطيع طفلك الضغط على زر التحدث وقول عدد أو أمر قصير مثل \"التالي\".",
"Speech is turned into text by your browser on this device; Tenbright uses it only if the browser can promise this happens on the device.":"يحوّل متصفحك الكلام إلى نص على هذا الجهاز؛ ولا يستخدمه Tenbright إلا إذا ضمن المتصفح أن ذلك يحدث على الجهاز.",
"The words are used once to read the answer and are then discarded.":"تُستخدم الكلمات مرة واحدة لقراءة الإجابة ثم تُحذف.",
"No audio and no transcript is recorded, kept or sent to us or anyone else.":"لا يُسجَّل أي صوت أو نص مكتوب، ولا يُحفظ، ولا يُرسل إلينا أو إلى أي جهة أخرى.",
"The microphone is used only after a tap on Talk, for one short answer.":"لا يُستخدم الميكروفون إلا بعد الضغط على زر التحدث، لإجابة قصيرة واحدة.",
"Pip never asks your child to say their name or anything about themselves.":"لا يطلب بيب أبدًا من طفلك أن يقول اسمه أو أي شيء عن نفسه.",
"You can switch voice answers off at any time.":"يمكنك إيقاف الإجابات الصوتية في أي وقت.",
"In the full product this step will use an FTC-recognized method of verifiable parental consent.":"في المنتج الكامل ستستخدم هذه الخطوة طريقة معتمدة لدى لجنة التجارة الفيدرالية (FTC) للتحقق من موافقة الوالدين.",
"This preview records your agreement on this device only.":"هذه النسخة التجريبية تسجّل موافقتك على هذا الجهاز فقط.",
"In this preview, everything stays in this browser on this device.":"في هذه النسخة التجريبية، يبقى كل شيء في هذا المتصفح على هذا الجهاز.",
"Nothing is sent to us or to anyone else.":"لا يُرسل أي شيء إلينا أو إلى أي جهة أخرى.",
"The app loads no outside fonts, analytics, ads or trackers.":"لا يحمّل التطبيق أي خطوط خارجية أو أدوات تحليل أو إعلانات أو أدوات تتبّع.",
"Pip's voice is recorded audio made with an AI voice model and included in the app; if a sentence has no recording, a voice built into your device reads it.":"صوت بيب تسجيل صوتي صُنع بنموذج صوتي بالذكاء الاصطناعي ومُضمَّن في التطبيق؛ وإذا لم يكن للجملة تسجيل، يقرؤها صوت مدمج في جهازك.",
"Speech recognition, if you turn it on, runs only on your device.":"التعرّف على الكلام، إن فعّلته، يعمل على جهازك فقط.",
