"Tenbright supports learning; it is not a replacement for a teacher, and it makes no promise of particular test results.":"يدعم Tenbright التعلّم؛ وهو ليس بديلًا عن المعلّم، ولا يعد بنتائج معيّنة في الاختبارات.",
