"Pip's puzzle: find {N} − {N} without breaking a ten!":"لغز بيب: أوجد {N} − {N} دون فكّ عشرة!",
"Take every digit from {N}, except the last one.":"اطرح كل رقم من {N}، ما عدا الرقم الأخير.",
"Take the last digit from {N}.":"اطرح الرقم الأخير من {N}.",
"{N} − {N}: {N} − {N} = {N}, {N} − {N} = {N}, so the answer is {N}.":"{N} − {N}: {N} − {N} = {N}، {N} − {N} = {N}، إذن الإجابة {N}.",
"It works because {N} is {N} + {N}, and {N} never needs regrouping.":"تنجح الطريقة لأن {N} = {N} + {N}، و{N} لا يحتاج أبدًا إلى إعادة تجميع.",
"All from {N}, and the last from {N}.":"الكل من {N}، والأخير من {N}.",
"{N} is {N} + {N}.":"{N} = {N} + {N}.",
"Subtract from the {N}s, then add the {N} to the last place.":"اطرح من أرقام {N}، ثم أضف {N} إلى المنزلة الأخيرة.",
"Play \"change from a dollar\": you spend {N}¢, how much change?":"العبوا لعبة \"الباقي من المئة\": إذا صرفت {N}، فكم الباقي؟",
"Use the all-from-{N} trick.":"استخدموا حيلة الكل من {N}.",
"This trick appears in the {N} book Vedic Mathematics by Bharati Krishna Tirtha.":"تظهر هذه الحيلة في كتاب «الرياضيات الفيدية» (Vedic Mathematics) الصادر عام {N} لبهاراتي كريشنا تيرثا (Bharati Krishna Tirtha).",
"Historians note it is not found in the ancient Vedas themselves.":"يشير المؤرخون إلى أنها غير موجودة في نصوص الفيدا القديمة نفسها.",
"We teach it because the math is sound and it is useful.":"نعلّمها لأن رياضياتها سليمة ومفيدة.",
"Fractions of a whole":"كسور الكل",
"Pip shares a lantern cake fairly.":"يقسم بيب كعكة الفانوس بالعدل.",
"The whole is cut into equal parts.":"يُقطع الكل إلى أجزاء متساوية.",
"The bottom number says how many equal parts.":"العدد السفلي يخبرنا كم جزءًا متساويًا.",
"The top number says how many parts we mean.":"العدد العلوي يخبرنا كم جزءًا نقصد.",
"How many equal parts are there in all?":"كم جزءًا متساويًا يوجد في المجموع؟",
"Bottom: equal parts in the whole.":"السفلي: الأجزاء المتساوية في الكل.",
"Top: parts we count.":"العلوي: الأجزاء التي نعدّها.",
"Cut a sandwich or paper into equal parts and name a fraction for some of them.":"قطّعوا شطيرة أو ورقة إلى أجزاء متساوية وسمّوا كسرًا لبعضها.",
"Fractions on a number line":"الكسور على خط الأعداد",
"Fractions live on the number line too.":"الكسور تسكن على خط الأعداد أيضًا.",
"Cut the space from {N} to {N} into equal jumps.":"قسّم المسافة من {N} إلى {N} إلى قفزات متساوية.",
"Each jump is one part, like {N}/{N}.":"كل قفزة جزء واحد، مثل {N}/{N}.",
"Count the jumps from {N} to find the fraction.":"عُدّ القفزات من {N} لتجد الكسر.",
"Count the jumps from {N}, not the marks.":"عُدّ القفزات من {N}، لا العلامات.",
"Each equal jump is one unit fraction.":"كل قفزة متساوية هي كسر وحدة واحد.",
"Fold a strip of paper into equal parts and label each fold from {N} to {N}.":"اطووا شريطًا من الورق إلى أجزاء متساوية واكتبوا على كل طيّة من {N} إلى {N}.",
"Place value to a million":"القيمة المنزلية حتى المليون",
"Pip counts the stars: hundreds of thousands!":"بيب يعدّ النجوم: مئات الآلاف!",
"Commas split big numbers into thousands and ones.":"الفواصل تقسم الأعداد الكبيرة إلى آلاف وآحاد.",
"Each place is {N} times the place to its right.":"كل منزلة تساوي {N} أضعاف المنزلة التي على يمينها.",
"In {N} the {N} is worth {N}.":"في {N} قيمة الرقم {N} هي {N}.",
"Which place is that digit in?":"في أي منزلة يقع هذا الرقم؟",
"Name the place, then multiply the digit by it.":"سمِّ المنزلة، ثم اضرب الرقم في قيمتها.",
"Read big numbers from the news or a map together and say what each digit is worth.":"اقرؤوا معًا أعدادًا كبيرة من الأخبار أو من خريطة، وقولوا قيمة كل رقم.",
"Compare big numbers":"مقارنة الأعداد الكبيرة",
"Which mountain is taller?":"أي جبل أعلى؟",
"More digits means a bigger number.":"أرقام أكثر تعني عددًا أكبر.",
"Same number of digits?":"عدد الأرقام نفسه؟",
"Compare from the left.":"قارن من اليسار.",
"The first place that differs decides.":"أول منزلة تختلف هي التي تقرّر.",
"Do they have the same number of digits?":"هل لهما عدد الأرقام نفسه؟",
"Compare from the biggest place to the smallest.":"قارن من المنزلة الكبرى إلى الصغرى.",
"Compare the populations of two towns or the prices of two cars.":"قارنوا عدد سكان بلدتين أو سعرَي سيارتين.",
"Round big numbers":"تقريب الأعداد الكبيرة",
"About how many?":"كم تقريبًا؟",
"Round it.":"قرّبه.",
"Find the two round numbers it sits between.":"أوجد العددين المقرّبين اللذين يقع بينهما.",
"Look at the next digit to the right.":"انظر إلى الرقم التالي على اليمين.",
"{N} or more rounds up; {N} or less rounds down.":"{N} أو أكثر نقرّب إلى الأعلى؛ {N} أو أقل نقرّب إلى الأدنى.",
"Which two round numbers is it between?":"بين أي عددين مقرّبين يقع؟",
"The digit to the right of the rounding place decides.":"الرقم الذي على يمين منزلة التقريب هو الذي يقرّر.",
"Round the cost of groceries to the nearest ten dollars and add in your head.":"قرّبوا ثمن المشتريات إلى أقرب عشر وحدات نقدية واجمعوها في الذهن.",
"Add and subtract big numbers":"جمع الأعداد الكبيرة وطرحها",
"Big numbers, same steps.":"أعداد كبيرة، والخطوات نفسها.",
"Start with the ones and move left.":"ابدأ بالآحاد وتحرّك إلى اليسار.",
"Regroup when a place has {N} or more, or not enough.":"أعد التجميع عندما تصل منزلة إلى {N} أو أكثر، أو عندما لا تكفي.",
"Which place do you start with?":"بأي منزلة تبدأ؟",
"Work from right to left, one place at a time.":"اعمل من اليمين إلى اليسار، منزلة واحدة في كل مرة.",
"Add or subtract two four-digit numbers from a receipt or scoreboard.":"اجمعوا أو اطرحوا عددين من أربعة أرقام من إيصال شراء أو لوحة نتائج.",
"Multiply by a {N}-digit number":"الضرب في عدد من {N} رقم",
