"Split {N} into {N}, {N} and {N}.":"قسّم {N} إلى {N} و{N} و{N}.",
"Multiply each part.":"اضرب كل جزء.",
"Add the parts together.":"اجمع الأجزاء معًا.",
"Split the big number into its places.":"قسّم العدد الكبير إلى منازله.",
"Multiply the parts, then add them.":"اضرب الأجزاء، ثم اجمعها.",
"Find the cost of {N} tickets at ${N} each by splitting {N} into {N}, {N} and {N}.":"أوجدوا ثمن {N} تذاكر سعر كل منها {N} بتقسيم {N} إلى {N} و{N} و{N}.",
"Multiply {N}-digit by {N}-digit":"ضرب عدد من {N} رقمين في عدد من {N} رقمين",
"Two {N}-digit numbers make a rectangle.":"عددان من {N} رقمين يكوّنان مستطيلًا.",
"Split both numbers into tens and ones.":"قسّم العددين كليهما إلى عشرات وآحاد.",
"Multiply all four parts.":"اضرب الأجزاء الأربعة كلها.",
"Add the four parts.":"اجمع الأجزاء الأربعة.",
"How many parts does the area model have?":"كم جزءًا في نموذج المساحة؟",
"Four parts: tens × tens, tens × ones, ones × tens, ones × ones.":"أربعة أجزاء: عشرات × عشرات، وعشرات × آحاد، وآحاد × عشرات، وآحاد × آحاد.",
