"{N} is neither.":"{N} ليس أوليًا ولا مؤلّفًا.",
"Can you find a factor other than {N} and the number?":"هل تجد عاملًا غير {N} والعدد نفسه؟",
"Try {N}, {N}, {N} and {N}.":"جرّب {N} و{N} و{N} و{N}.",
"Try to arrange {N} coins and then {N} coins into rectangles.":"حاولوا ترتيب {N} قطع نقدية ثم {N} قطعة في مستطيلات.",
"Which has more ways?":"أيهما له طرق أكثر؟",
"Times as many":"أضعاف العدد",
