"Times as many means multiply.":"الأضعاف تعني الضرب.",
"Compare: \"My pencil is {N} cm.":"قارنوا: \"طول قلمي {N} سم.",
"Yours is {N} times as long.":"وطول قلمك {N} أضعافه.",
"How long?\"":"فكم طوله؟\"",
"Number patterns":"أنماط الأعداد",
"Find the rule and keep the pattern going.":"أوجد القاعدة وأكمل النمط.",
"Look at how each number changes.":"انظر كيف يتغيّر كل عدد.",
"Say the rule: add {N}, or multiply by {N}.":"قل القاعدة: أضف {N}، أو اضرب في {N}.",
"Use the rule on the last number.":"طبّق القاعدة على العدد الأخير.",
"How does each number change?":"كيف يتغيّر كل عدد؟",
"Find the rule, then apply it once more.":"أوجد القاعدة، ثم طبّقها مرة أخرى.",
