"Then compare the tops.":"ثم قارن البسوط.",
"Same top?":"البسط نفسه؟",
"The smaller bottom is the bigger piece.":"المقام الأصغر يعني القطعة الأكبر.",
"Can you make the bottoms match?":"هل تستطيع جعل المقامات متساوية؟",
