"Same-size pieces add up like counting.":"القطع المتساوية في الحجم تُجمع كما نعدّ.",
"The bottom number names the piece size.":"المقام يسمّي حجم القطعة.",
"Add or take away the tops.":"اجمع البسوط أو اطرحها.",
