"Mixes up the tenths and hundredths places.":"يخلط بين منزلتَي الأعشار والأجزاء من مئة.",
"Tenths and hundredths swapped":"تبديل الأعشار والأجزاء من مئة",
"Line up the decimal points first.":"رتّب الفواصل العشرية أولًا.",
"Lines up the last digits instead of the decimal points when adding or subtracting decimals.":"يرتّب الأرقام الأخيرة بعضها تحت بعض بدلًا من الفواصل العشرية عند جمع الأعداد العشرية أو طرحها.",
"Lined up the last digits":"رتّب الأرقام الأخيرة",
"Count the decimal places.":"عُدّ المنازل العشرية.",
"Does the size of the answer make sense?":"هل حجم الإجابة منطقي؟",
"Multiplies or divides correctly but puts the decimal point in the wrong place.":"يضرب أو يقسم بشكل صحيح لكنه يضع الفاصلة العشرية في المكان الخطأ.",
"Decimal point in the wrong place":"الفاصلة العشرية في المكان الخطأ",
"How many halves fit in one whole?":"كم نصفًا يتسع في الواحد الكامل؟",
"Thinks dividing always makes a number smaller, so multiplies when dividing by a fraction or decimal under {N}.":"يظن أن القسمة تصغّر العدد دائمًا، فيضرب عند القسمة على كسر أو عدد عشري أقل من {N}.",
"Dividing always makes smaller":"القسمة تصغّر دائمًا",
"Each part has a place value.":"لكل جزء قيمة منزلية.",
"Multiplies each digit but writes the products side by side instead of adding them with their place values.":"يضرب كل رقم لكنه يكتب النواتج متجاورة بدلًا من جمعها بقيمها المنزلية.",
"Products written side by side":"نواتج مكتوبة متجاورة",
