"With a parent's consent, the app keeps a child's nickname and birth year, and a record of their answers: which skill, whether it was right, which hints they used, which strategy they chose and how long they took, plus how close their number-line warm-up estimates were, the badges they earned and the look they chose for Pip.":"بموافقة أحد الوالدين، يحتفظ التطبيق بالاسم المستعار للطفل وسنة ميلاده، وبسجل لإجاباته: أي مهارة، وهل كانت صحيحة، وأي تلميحات استخدم، وأي استراتيجية اختار، وكم استغرق من الوقت، إضافة إلى مدى قرب تقديراته في تمارين إحماء خط الأعداد، والأوسمة التي كسبها، والمظهر الذي اختاره لبيب.",
