"Then split it into equal weekly amounts.":"ثم قسّمه إلى مبالغ أسبوعية متساوية.",
"The number of weeks is the answer.":"عدد الأسابيع هو الجواب.",
"How much is still needed?":"كم ما زال مطلوبًا؟",
