"Owning part of a company.":"امتلاك جزء من شركة.",
"A company can be split into equal parts called shares.":"يمكن تقسيم الشركة إلى أجزاء متساوية تُسمّى أسهمًا.",
"Owning some shares means owning part of the company.":"امتلاك بعض الأسهم يعني امتلاك جزء من الشركة.",
"Each share gets an equal part of the profit.":"كل سهم يأخذ جزءًا متساويًا من الربح.",
"Profit can be smaller next year, so a share is not a promise.":"قد يكون الربح أصغر في السنة القادمة، لذا السهم ليس وعدًا.",
"How much does one share get?":"كم يأخذ سهم واحد؟",
"The profit for one share, times the shares you own.":"ربح السهم الواحد، ضرب الأسهم التي تملكها.",
