"At ${N} a cup, only {N} cups sold.":"بسعر {N} دولار للكوب، بيع {N} كوبًا فقط.",
"The cups cost ${N} each.":"تكلفة كل كوب {N} دولار.",
"What is the profit at ${N}?":"كم الربح بسعر {N} دولار؟",
"Which price made more profit this time?":"أي سعر حقق ربحًا أكبر هذه المرة؟",
"At ${N} the profit is {N}.":"بسعر {N} دولار الربح {N}.",
"Profit at ${N}":"الربح بسعر {N} دولار",
"You made {N} cups.":"صنعتَ {N} كوبًا.",
"How many dollars did they cost?":"كم دولارًا كلّفت؟",
"Only {N} cups sold, at ${N} each.":"بيع {N} كوبًا فقط، بسعر {N} دولار للكوب.",
"How many dollars bigger are the costs than the sales?":"بكم دولارًا تزيد التكاليف على المبيعات؟",
