"Shoes cost ${N}.":"الحذاء ثمنه {N} دولار.",
"What is {N} rounded to the nearest ten?":"ما {N} مقرّبًا إلى أقرب عشرة؟",
"It is closer to {N}.":"إنه أقرب إلى {N}.",
