"What is the estimate?":"كم التقدير؟",
"Now add the real prices.":"الآن اجمع الأسعار الحقيقية.",
"How many dollars in all?":"كم دولارًا في المجموع؟",
"How many dollars are left from ${N}?":"كم دولارًا يبقى من {N} دولار؟",
