"The change is both jumps together.":"الباقي هو القفزتان معًا.",
"A clock has two hands.":"للساعة عقربان.",
"Look at the short hand.":"انظر إلى العقرب القصير.",
"It shows the hour.":"إنه يدلّ على الساعة.",
"So the hour is {N}.":"إذن الساعة {N}.",
"Now look at the long hand.":"الآن انظر إلى العقرب الطويل.",
"It points straight down at {N}.":"إنه يشير إلى الأسفل مباشرة، إلى {N}.",
"That is half way around: half past.":"هذا نصف الدورة: والنصف.",
"Say the hour, then the minutes.":"قل الساعة، ثم الدقائق.",
"It points at {N}, so the hour is {N}.":"إنه يشير إلى {N1}، إذن الساعة {N2}.",
"It points straight up at {N}.":"إنه يشير إلى الأعلى مباشرة، إلى {N}.",
"That means {N} minutes, so we say o’clock.":"هذا يعني {N} دقيقة، فنقول: تمامًا.",
"The minutes tell how far past the hour it is.":"الدقائق تخبرنا كم مضى بعد الساعة.",
"It points to {N}.":"إنه يشير إلى {N}.",
"Each number on the clock is {N} minutes.":"كل رقم على الساعة يساوي {N} دقائق.",
"It is {N} marks past {N}.":"إنه بعد {N2} بـ {N1} علامات.",
"Count by {N}s up to {N}.":"عُدّ بالخمسات حتى {N2}.",
"Then each small mark is {N} minute.":"ثم كل علامة صغيرة دقيقة واحدة.",
"It is {N} mark past {N}.":"إنه بعد {N2} بعلامة واحدة.",
"The {N} means {N} minutes.":"الرقم {N1} يعني {N2} دقيقة.",
"Each small mark is {N} minute.":"كل علامة صغيرة دقيقة واحدة.",
"Elapsed time is how long something lasts.":"الوقت المنقضي هو المدة التي يستغرقها شيء ما.",
"Count on from the start time to the end time.":"عُدّ من وقت البداية إلى وقت النهاية.",
"An hour is {N} minutes.":"الساعة {N} دقيقة.",
"Jump whole hours first.":"اقفز بالساعات الكاملة أولًا.",
"That is {N} minutes.":"هذا {N} دقيقة.",
"Add the hours and the minutes together.":"اجمع الساعات والدقائق معًا.",
"Jump to the next hour first.":"اقفز إلى الساعة التالية أولًا.",
"Then count the minutes after the hour.":"ثم عُدّ الدقائق بعد الساعة.",
"Both times have the same hour.":"للوقتين الساعة نفسها.",
"So we only need the minutes.":"لذلك نحتاج إلى الدقائق فقط.",
"Take the start minutes from the end minutes.":"اطرح دقائق البداية من دقائق النهاية.",
"Jump whole hours.":"اقفز بالساعات الكاملة.",
"It ends right on the hour, at {N}:{N}.":"ينتهي تمامًا عند الساعة {N}:{N}.",
"An hour has {N} minutes.":"في الساعة {N} دقيقة.",
"The start is {N} minutes past.":"البداية بعد الساعة بـ {N} دقيقة.",
"Length is how many units long something is.":"الطول هو عدد الوحدات التي يمتدّها الشيء.",
"A unit is one space between two marks on the ruler.":"الوحدة هي مسافة واحدة بين علامتين على المسطرة.",
"Look where it starts.":"انظر من أين يبدأ.",
"When it starts at {N}, the end mark tells the length.":"عندما يبدأ عند {N}، علامة النهاية تخبرنا بالطول.",
"So the end mark is not the length.":"إذن علامة النهاية ليست الطول.",
"Count the spaces from {N} to {N}.":"عُدّ المسافات من {N} إلى {N}.",
"Or take the start from the end.":"أو اطرح البداية من النهاية.",
"Check: count on from {N} to {N}.":"تحقّق: عُدّ من {N} إلى {N}.",
"You make {N} jumps.":"تقفز {N} قفزات.",
"\"How much longer\" compares two lengths.":"«كم أطول» تقارن بين طولين.",
"Compare the two ribbons.":"قارن بين الشريطين.",
"How much longer asks for the difference, so we take away.":"«كم أطول» تسأل عن الفرق، لذلك نطرح.",
"The two length sides: {N} + {N} = {N}":"ضلعا الطول: {N} + {N} = {N}",
"The two width sides share the rest: {N} − {N} = {N}":"ضلعا العرض يتقاسمان الباقي: {N} − {N} = {N}",
"Each width side is half of that: {N} ÷ {N} = {N}":"كل ضلع للعرض نصف ذلك: {N} ÷ {N} = {N}",
"Perimeter is the distance all the way around a shape.":"المحيط هو المسافة حول الشكل كله.",
"The perimeter is all {N} sides added together.":"المحيط هو مجموع الأضلاع الـ {N}.",
"Two of the sides are the length, {N} each.":"ضلعان منها هما الطول، {N} لكل منهما.",
"The other two sides share what is left.":"الضلعان الآخران يتقاسمان ما تبقّى.",
"Those two sides are the same, so split it in half.":"هذان الضلعان متساويان، فاقسمه نصفين.",
"The sides across from each other are the same length.":"الأضلاع المتقابلة لها الطول نفسه.",
"Go all the way around and add each side.":"دُر حول الشكل كله واجمع كل ضلع.",
"Count the rows, then the squares in one row.":"عُدّ الصفوف، ثم المربعات في صف واحد.",
"Every row has the same number of squares.":"في كل صف العدد نفسه من المربعات.",
"Area is how many unit squares cover a shape.":"المساحة هي عدد مربعات الوحدة التي تغطي الشكل.",
"Picture unit squares covering the rectangle.":"تخيّل مربعات وحدة تغطي المستطيل.",
"There are {N} rows of {N} squares.":"هناك {N} صفوف في كل منها {N} مربعات.",
"So area is the length times the width.":"إذن المساحة هي الطول ضرب العرض.",
"Multiply the length by the width.":"اضرب الطول في العرض.",
"Shapes are named by how many straight sides they have.":"تُسمّى الأشكال بحسب عدد أضلاعها المستقيمة.",
"The start of the name is a clue.":"بداية الاسم دليل.",
"Tri means {N}.":"«ثلاثي» يعني {N}.",
"Check: draw one and count its sides.":"تحقّق: ارسم واحدًا وعُدّ أضلاعه.",
"Quad means {N}.":"«رباعي» يعني {N}.",
"Hexa means {N}.":"«سداسي» يعني {N}.",
"Touch each straight side as you count.":"المس كل ضلع مستقيم وأنت تعدّ.",
